export { Badge, badgeVariants }

/**
 * Vendored from shadcn/ui registry (style new-york-v4): https://ui.shadcn.com/r/styles/new-york-v4/button.json
 * Item: button. Fetched 2026-08-31. Do not edit unless intentionally adopting upstream changes.
